  while (rightChildIndex < _length) {
    var leftChildIndex = rightChildIndex - 1;
    var leftChild = _elementAt(leftChildIndex);
    var rightChild = _elementAt(rightChildIndex);
    var comp = comparison(leftChild, rightChild);
    int minChildIndex;
