  var left = after.width;
  var top = after.height;
  var right = -1;
  var bottom = -1;

  for (var y = 0; y < after.height; y++) {
    for (var x = 0; x < after.width; x++) {
      final a = before.getPixel(x, y);
      final b = after.getPixel(x, y);
      final difference = [
        (a.r - b.r).abs(),
        (a.g - b.g).abs(),
        (a.b - b.b).abs(),
        (a.a - b.a).abs(),
