WhenComplete _handleAsync(
  Ref ref,
  AsyncSubscription? Function({
    required void Function(ValueT) data,
    required void Function(Object, StackTrace) error,
    required void Function() done,
    required void Function(Future<ValueT>) last,
  })
  listen,
) {
  void callOnError(Object error, StackTrace stackTrace) {
    onValue(triggerRetry(error, stackTrace), seamless: !ref.isReload);
  }

  void Function()? onDone;
  var isDone = false;

  try {
    _cancelSubscription = listen(
      data: (value) {
        onData(AsyncData(value), seamless: !ref.isReload);
      },
      error: callOnError,
      last: (last) {
        assert(_lastFuture == null, 'bad state');
        _lastFuture = last;
      },
      done: () {
        _lastFuture = null;
        isDone = true;
        onDone?.call();
      },
    );
  } on AsyncValueIsLoadingException {
    // Those are typically coming from `ref.watch(provider).requireValue`,
    // which counts as an abort while the provider is still loading.
    // We purposefully want to keep `provider.future` pending when such an
    // exception is thrown, instead of treating it as an error.
  } catch (error, stackTrace) {
    callOnError(error, stackTrace);
  }

  return (onDoneCb) {
    onDone = onDoneCb;
    // Handle synchronous completion
