/// Removes and disposes the [current] element, while iterating over the queue. It is an error to call this method while not iterating, or to access the [current] element after it was removed.
void removeCurrent() {
  assert(
    _currentIndex >= 0,
    'Cannot remove current element if not iterating',
  );
  _elements[_currentIndex].dispose();
  if (_startIndex == _endIndex) {
    assert(_currentIndex == _startIndex);
    _startIndex = -1;
    _endIndex = -1;
    _currentIndex = -1;
  } else if (_currentIndex == _startIndex) {
    _startIndex += 1;
    if (_startIndex == _elements.length) {
      _startIndex = 0;
    }
  } else {
    _indicesToRemove.add(_currentIndex);
  }
}
