/// Consumes whitespace at the start of the line (if any) and emits indent/ dedent tokens according to the indent stack. Always returns true (even if a line had 0 spaces).
bool eatIndent() {
  final position0 = position;
  var lineIndent = 0;
  while (true) {
    final cu = currentCodeUnit;
    if (cu == $space) {
      lineIndent += 1;
    } else if (cu == $tab) {
      lineIndent += 4;
    } else {
      break;
    }
    position += 1;
  }
  if (lineIndent > indentStack.last) {
    indentStack.add(lineIndent);
    pushToken(Token.startIndent, position0);
  }
  while (lineIndent < indentStack.last) {
    indentStack.removeLast();
    pushToken(Token.endIndent, position0);
  }
  if (lineIndent > indentStack.last) {
    error('inconsistent indentation');
  }
  return true;
}
