static bool isClockwise(List<Vector2> vertices) {
  var area = 0.0;
  for (var i = 0; i < vertices.length; i++) {
    final j = (i + 1) % vertices.length;
    area += vertices[i].x * vertices[j].y - vertices[j].x * vertices[i].y;
