File? findProjectFile(Directory directory, String name) {
  var current = directory.absolute;
  while (true) {
    final file = projectFile(current, name);
    if (file.existsSync()) {
      return file;
    }
    final parent = current.parent;
    if (parent.path == current.path) {
      return null;
    }
    current = parent;
  }
}
