/// The cumulative weight of the (sub-)path from `path[from]` to `path[to]`. If [to] is less than [from], the sub-path is traversed in reverse. The values in `path` should be vertices in this graph.
int pathWeight(List<int> path, int from, int to) {
  var weight = 0;
  var cursor = path[from];
  var step = from <= to ? 1 : -1;
  for (var i = from; i != to;) {
    i += step;
    var next = path[i];
    weight += this.weight(cursor, next);
    cursor = next;
  }
  return weight;
}
