/// Keeps the nodes of the tree that [matches], together with their ancestors and their descendants, so that the path to every match is preserved and the matches are shown in full. Returns null if neither the node nor any of its descendants match.
Map<String, dynamic>? filterComponentTree(
  Map<String, dynamic> node,
  bool Function(Map<String, dynamic> node) matches,
) {
  if (matches(node)) {
    return node;
  }
  final children = (node['children'] as List)
      .map(
        (child) => filterComponentTree(child as Map<String, dynamic>, matches),
      )
      .nonNulls
      .toList();
  if (children.isEmpty) {
    return null;
  }
  return {...node, 'children': children};
}
