    var breakAt = cursor;
    var char = base.codeUnitAt(--cursor);
    if (char & 0xFC00 != 0xDC00) {
      state = moveBack(state, low(char));
      if (state >= stateLookaheadMin) state = _lookAhead(state);
      if (state & stateNoBreak == 0) {
        return breakAt;
